    chapterRef: "cf. Murtagh's General Practice, Ch. 116 \"Common lumps and bumps\"",
    differentials: [
      { condition: "Lipoma", note: "Soft, mobile, slow-growing, painless — the most common benign subcutaneous lump." },
      { condition: "Epidermoid (sebaceous) cyst", note: "Firm, mobile, often with a visible central punctum; can become inflamed or infected." },
      { condition: "Abscess", note: "Tender, warm, fluctuant swelling, often with surrounding erythema." },
      { condition: "Ganglion cyst", note: "Common near joints/tendons (e.g. wrist), firm and cystic." },
      { condition: "Soft tissue sarcoma", note: "A rapidly growing, deep, or larger-than-5cm lump — a red flag requiring imaging and specialist referral." },
    ],
    source: { title: "Epidermoid Cyst", org: "StatPearls (NCBI Bookshelf), National Library of Medicine, NIH, USA", url: "https://www.ncbi.nlm.nih.gov/books/NBK499974/" },
