    chapterRef: "cf. Murtagh's General Practice, Ch. 94 \"Abnormal uterine bleeding\"",
    differentials: [
      { condition: "Uterine fibroids (leiomyoma)", note: "Heavy or prolonged bleeding, sometimes with pelvic pressure or a palpable mass." },
      { condition: "Anovulatory bleeding", note: "Irregular, unpredictable bleeding, common around menarche and perimenopause." },
      { condition: "Endometrial polyp", note: "Intermenstrual spotting or irregular bleeding, often diagnosed on ultrasound." },
      { condition: "Pregnancy-related bleeding", note: "Always exclude pregnancy (including ectopic or miscarriage) in a woman of reproductive age." },
      { condition: "Endometrial malignancy", note: "Consider especially with postmenopausal bleeding, or in a woman with risk factors — a red flag requiring prompt investigation." },
    ],
    source: { title: "Abnormal Uterine Bleeding", org: "StatPearls (NCBI Bookshelf), National Library of Medicine, NIH, USA", url: "https://www.ncbi.nlm.nih.gov/books/NBK532913/" },
