// --- Medication safety reference (contraindications / adverse events / interactions) ---
// Reference-level, well-established prescribing information. Not exhaustive —
// always cross-check against current prescribing information before dispensing.

const DRUG_SAFETY = {
  Amlodipine: {
    contraindications: ["Severe hypotension", "Cardiogenic shock", "Severe symptomatic aortic stenosis"],
    adverseEvents: ["Peripheral oedema", "Flushing", "Headache", "Palpitations"],
    allergyFlags: [],
    interactsWith: { Telmisartan: "Additive hypotensive effect — monitor BP closely, especially at initiation." },
  },
  Telmisartan: {
    contraindications: ["Pregnancy", "Bilateral renal artery stenosis", "Concurrent aliskiren use in diabetic patients"],
    adverseEvents: ["Hyperkalaemia", "Dizziness", "Rare renal impairment"],
    allergyFlags: [],
    interactsWith: { Amlodipine: "Additive hypotensive effect — monitor BP closely, especially at initiation." },
  },
  Azithromycin: {
    contraindications: ["Known hypersensitivity to macrolide antibiotics", "History of cholestatic jaundice with prior azithromycin use"],
    adverseEvents: ["GI upset", "Diarrhoea", "Rare QT prolongation"],
    allergyFlags: ["Macrolide", "Azithromycin"],
    interactsWith: { Warfarin: "May potentiate anticoagulant effect — monitor INR if co-prescribed." },
  },
  "Zoledronic acid": {
    contraindications: ["Severe renal impairment (CrCl < 35 mL/min)", "Uncorrected hypocalcaemia"],
    adverseEvents: ["Post-infusion flu-like symptoms", "Hypocalcaemia", "Rare osteonecrosis of the jaw with long-term use"],
    allergyFlags: [],
    interactsWith: { Aminoglycosides: "Additive risk of hypocalcaemia and renal toxicity." },
  },
};

function checkAllergyMatch(allergies, flags) {
  return allergies.some((a) => flags.some((f) => a.toLowerCase().includes(f.toLowerCase()) || f.toLowerCase().includes(a.toLowerCase())));
}

function redactPolicy(policy) {
  if (!policy) return "no policy number on file";
  const digits = policy.trim();
  if (digits.length <= 4) return digits;
  return `••••${digits.slice(-4)}`;
}

// --- Treatment summary: history of present illness, tests, course, --------
// treatment given, follow-up advice, precautions — assembled from records
// already on file, usable identically from the doctor and patient sides.

function buildTreatmentSummary(patient) {
  const enc = patient.encounters[0];
  const meta = enc ? DIAGNOSIS_META[enc.diagnosisKey] : null;
  const followup = FOLLOWUPS.find((f) => f.patient === patient.name);
  const tests = meta ? [...meta.tests.blood, ...meta.tests.urine, ...meta.tests.radiological, ...meta.tests.microbiological, ...meta.tests.immunological] : [];
  return {
    patientName: patient.name,
    age: patient.age,
    gender: patient.gender,
    date: enc?.date || "—",
    hpi: enc?.complaint || "Not recorded",
    diagnosis: enc?.diagnosis || "Not recorded",
    tests,
    course: enc?.notes || "Not recorded",
    treatment: patient.prescriptions.map((rx) => `${rx.drug} — ${rx.dosage}`),
    followUpAdvice: followup?.takeaways || FOLLOWUP_DEFAULTS.takeaways,
    precautions: followup?.precautions || FOLLOWUP_DEFAULTS.precautions,
    nextVisit: followup?.nextVisit || FOLLOWUP_DEFAULTS.nextVisit,
  };
}

// Case-highlight posts are entirely doctor-written now — three short fields
// (notable clinical considerations, disease course, workup) that the doctor
// fills in themselves. Nothing here auto-pulls from the chart; this just
// formats what the doctor wrote for display/publishing.
function formatCaseHighlight({ findings, course, workup }) {
  const parts = [];
  if (findings?.trim()) parts.push(`Notable clinical considerations: ${findings.trim()}`);
  if (course?.trim()) parts.push(`Disease course: ${course.trim()}`);
  if (workup?.trim()) parts.push(`Workup: ${workup.trim()}`);
  return parts.join(" ");
}

function summaryToText(s) {
  return `TREATMENT SUMMARY
Patient: ${s.patientName} (${s.age} yrs, ${s.gender})
Date: ${s.date}

HISTORY OF PRESENT ILLNESS
${s.hpi}

DIAGNOSIS
${s.diagnosis}

TESTS DONE / RECOMMENDED
${s.tests.join(", ") || "None recorded"}

COURSE OF DISEASE
${s.course}

TREATMENT GIVEN
${s.treatment.join("\n") || "None recorded"}

FOLLOW-UP ADVICE
${s.followUpAdvice}

PRECAUTIONS TO BE TAKEN
${s.precautions}

NEXT VISIT
${s.nextVisit}

— ClairMD Clinic`;
}

function downloadText(filename, text) {
  const blob = new Blob([text], { type: "text/plain" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a");
  a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
}

function printSummary(text, title) {
  const w = window.open("", "_blank");
  if (!w) return;
  w.document.write(`<title>${title}</title><pre style="font-family: 'IBM Plex Sans', sans-serif; white-space: pre-wrap; padding: 32px; font-size: 14px; line-height: 1.6;">${text.replace(/</g, "&lt;")}</pre>`);
  w.document.close();
  w.focus();
  w.print();
}

// ---------------------------------------------------------------------------
// Backend sync (prototype) — talks to clairmd-backend's real /api/auth,
// /api/record-content, /api/coadmin, and /api/drive endpoints (see that
// repo's README). Scoped narrowly on purpose:
//
// - Auth: this prototype has no session/context layer threading an
//   account through the whole app, so the token lives in localStorage and
//   is read fresh wherever it's needed — a real app would hoist this into
//   a proper auth context instead.
// - Encryption key: each record gets its own AES-GCM key, generated in
//   the browser and cached in localStorage. For the record's OWNER
//   (the primary doctor) that's the whole story. For a co-admin or
//   patient, that same key is real-key-wrapped with RSA-OAEP per
//   recipient (record_key_wraps, routes/coadmin.js) — see the "Co-admin
//   key-wrap crypto" section of this repo's README for the full design
//   and its own known limitations (no cross-device key recovery, no
//   revocation).
// - Google Drive: each note is encrypted client-side and both (a) synced
//   to this backend's own opaque-blob store (patient_record_content —
//   works even if Drive is never connected) and (b) uploaded, still as
//   ciphertext, to a dedicated non-descriptive folder in the doctor's OWN
//   Drive via the Drive REST API directly from the browser, using a
//   short-lived access token minted by GET /api/drive/access-token. This
//   backend brokers the OAuth handshake and hands out that access token,
//   but the file content itself never passes through it — same trust
//   model as record_key_wraps. See uploadEncryptedBlobToDrive/
//   downloadEncryptedBlobFromDrive below.
// ---------------------------------------------------------------------------

// getApiBase/getAuthToken/setAuthToken/apiRequest/backendSignup/
// backendLogin/backendLogout moved to ./api.js so LandingPage.jsx can call
// the exact same real auth logic instead of re-implementing it — see that
// file for the (unchanged) implementations.

// --- Per-record AES-GCM key (prototype-only local key store — see the
// module comment above for why this stands in for the real key-wrap
// scheme). ---
async function getOrCreateRecordKey(recordId) {
  if (!(typeof crypto !== "undefined" && crypto.subtle)) {
    throw new Error("Encryption isn't available in this browser context (Web Crypto requires https or localhost).");
  }
  const storageKey = `clair_record_key_${recordId}`;
  const existing = localStorage.getItem(storageKey);
  if (existing) {
    const raw = Uint8Array.from(atob(existing), (c) => c.charCodeAt(0));
    return crypto.subtle.importKey("raw", raw, "AES-GCM", true, ["encrypt", "decrypt"]);
  }
  const key = await crypto.subtle.generateKey({ name: "AES-GCM", length: 256 }, true, ["encrypt", "decrypt"]);
  const raw = new Uint8Array(await crypto.subtle.exportKey("raw", key));
  localStorage.setItem(storageKey, btoa(String.fromCharCode(...raw)));
  return key;
}

function bytesToBase64(bytes) {
  let binary = "";
  bytes.forEach((b) => { binary += String.fromCharCode(b); });
  return btoa(binary);
}
function base64ToBytes(b64) {
  return Uint8Array.from(atob(b64), (c) => c.charCodeAt(0));
}

// Encrypted blob format: base64(12-byte IV || AES-GCM ciphertext+tag) — a
// single opaque string, matching what patient_record_content.encrypted_blob
// expects (schema.sql: "opaque ciphertext; backend never decrypts this").
async function encryptRecordText(recordId, plaintext) {
  const key = await getOrCreateRecordKey(recordId);
  const iv = crypto.getRandomValues(new Uint8Array(12));
  const ciphertext = new Uint8Array(await crypto.subtle.encrypt({ name: "AES-GCM", iv }, key, new TextEncoder().encode(plaintext)));
  const combined = new Uint8Array(iv.length + ciphertext.length);
  combined.set(iv, 0);
  combined.set(ciphertext, iv.length);
  return bytesToBase64(combined);
}

async function decryptRecordText(recordId, encryptedBlob) {
  const key = await getOrCreateRecordKey(recordId);
  const combined = base64ToBytes(encryptedBlob);
  const iv = combined.slice(0, 12);
  const ciphertext = combined.slice(12);
  const plaintext = await crypto.subtle.decrypt({ name: "AES-GCM", iv }, key, ciphertext);
  return new TextDecoder().decode(plaintext);
}

// True only if THIS browser already holds the actual AES key it used to
// encrypt a given record (i.e. it's the browser that created/synced that
// record's content — see getOrCreateRecordKey above). Deliberately does
// NOT call getOrCreateRecordKey itself: that function generates a fresh
// key on a cache miss, which is correct when a record is first created,
// but wrong here — silently generating a "key" for a record whose real
// key lives on a different device would produce a wrap that looks valid
// but can't decrypt anything real. Used to filter which records are safe
// to wrap for a co-admin (see assignCoAdminOnBackend below).
function hasLocalRecordKey(recordId) {
  return typeof localStorage !== "undefined" && !!localStorage.getItem(`clair_record_key_${recordId}`);
}

// --- Per-account RSA-OAEP keypair — the real key-wrap crypto for co-admin
// access (routes/coadmin.js), replacing the "not built yet" gap this
// prototype had before. The private key is generated in the browser and
// NEVER leaves it (not even to this app's own backend); only the public
// key (SPKI, base64) is published via PUT /api/auth/public-key so other
// accounts can wrap a record's AES key for this one. This is genuinely
// the same trust model as record_key_wraps itself: the backend routes
// ciphertext, never sees a plaintext key.
//
// Known, explicitly-accepted limitation: there's no key backup/recovery
// flow. If this account logs in from a second browser/device, that
// browser has no private key, so it can't unwrap anything wrapped for the
// first one's public key — and (see below) this function refuses to
// silently generate a second keypair and overwrite the published public
// key, since that would orphan every wrap already made for the first one.
// A real deployment needs a proper backup/recovery design (e.g. a
// password-derived wrap of the private key); not attempted here.
async function getOrCreateKeyPair() {
  if (!(typeof crypto !== "undefined" && crypto.subtle)) {
    throw new Error("Encryption isn't available in this browser context (Web Crypto requires https or localhost).");
  }
  const storedPrivate = localStorage.getItem("clair_private_key");
  if (storedPrivate) {
    return crypto.subtle.importKey("pkcs8", base64ToBytes(storedPrivate), { name: "RSA-OAEP", hash: "SHA-256" }, false, ["unwrapKey"]);
  }

  const me = await apiRequest("/auth/me");
  if (me.account.public_key) {
    throw new Error("This account already has a co-admin key published from a different device, and this browser doesn't have the matching private key. Multi-device key recovery isn't built in this prototype.");
  }

  const keyPair = await crypto.subtle.generateKey(
    { name: "RSA-OAEP", modulusLength: 2048, publicExponent: new Uint8Array([1, 0, 1]), hash: "SHA-256" },
    true,
    ["wrapKey", "unwrapKey"]
  );
  const privateRaw = new Uint8Array(await crypto.subtle.exportKey("pkcs8", keyPair.privateKey));
  localStorage.setItem("clair_private_key", bytesToBase64(privateRaw));
  const publicRaw = new Uint8Array(await crypto.subtle.exportKey("spki", keyPair.publicKey));
  await apiRequest("/auth/public-key", { method: "PUT", body: { publicKey: bytesToBase64(publicRaw) } });
  return keyPair.privateKey;
}

// Wraps one record's existing AES-GCM key with a recipient's RSA-OAEP
// public key (SPKI, base64, as returned by the account-directory search or
// GET /api/auth/me) — the actual crypto behind co-admin assignment. Only
// ever called on a record this browser already holds the real key for
// (see hasLocalRecordKey).
async function wrapRecordKeyForRecipient(recordId, recipientPublicKeyB64) {
  const aesKey = await getOrCreateRecordKey(recordId);
  const publicKey = await crypto.subtle.importKey(
    "spki",
    base64ToBytes(recipientPublicKeyB64),
    { name: "RSA-OAEP", hash: "SHA-256" },
    false,
    ["wrapKey"]
  );
  const wrapped = new Uint8Array(await crypto.subtle.wrapKey("raw", aesKey, publicKey, { name: "RSA-OAEP" }));
  return bytesToBase64(wrapped);
}

// Co-admin/patient side: fetches this account's wrapped key for a record
// (subject to coadmin.js's consent gate), unwraps it with this account's
// own private key, and caches the result in the SAME localStorage slot
// getOrCreateRecordKey reads from — so the existing encrypt/decrypt
// helpers (and syncNoteToBackend's round trip) work completely unchanged
// for a co-admin, exactly the way they already do for the primary doctor.
async function fetchAndCacheWrappedRecordKey(recordId) {
  const data = await apiRequest(`/coadmin/key-wraps/${recordId}`);
  const privateKey = await getOrCreateKeyPair();
  const aesKey = await crypto.subtle.unwrapKey(
    "raw",
    base64ToBytes(data.wrappedKey),
    privateKey,
    { name: "RSA-OAEP" },
    { name: "AES-GCM", length: 256 },
    true,
    ["encrypt", "decrypt"]
  );
  const rawKey = new Uint8Array(await crypto.subtle.exportKey("raw", aesKey));
  localStorage.setItem(`clair_record_key_${recordId}`, bytesToBase64(rawKey));
}

// Full read path for a co-admin viewing a record they've been granted
// (and consented) access to: unwrap the key, fetch the encrypted content,
// decrypt it locally. Mirrors syncNoteToBackend's round trip but read-only.
async function loadCoAdminRecordContent(recordId) {
  await fetchAndCacheWrappedRecordKey(recordId);
  const data = await apiRequest(`/record-content/${recordId}`);
  return decryptRecordText(recordId, data.content.encrypted_blob);
}

// Creates the backend pointer row (patient_record_index) this note's
// content will hang off of. driveFileId starts as a placeholder — if this
// doctor has Google Drive connected, syncNoteToBackend below overwrites it
// with the real Drive file id once the actual upload succeeds (see PATCH
// /api/records/:id there). Until then, or if Drive is never connected,
// this stays a placeholder and the backend's own opaque-blob store
// (patient_record_content) is the only place the content actually lands —
// that path works independently either way.
async function ensureBackendRecord(noteType) {
  const data = await apiRequest("/records", { method: "POST", body: { driveFileId: `clair-prototype-${Date.now()}`, noteType } });
  return data.record.id;
}

// --- Google Drive — the actual upload/download half of "encrypt before
// upload, decrypt after download" (routes/drive.js handles only the OAuth
// handshake + a short-lived access token; everything below talks to the
// real Drive REST API directly from the browser, exactly like this file's
// header comment describes). -----------------------------------------------

const DRIVE_UPLOAD_URL = "https://www.googleapis.com/upload/drive/v3/files";
const DRIVE_FILES_URL = "https://www.googleapis.com/drive/v3/files";

// Access tokens are short-lived (~1h) and deliberately kept in memory
// only, never localStorage — unlike the auth JWT, there's no reason for
// this one to survive a page reload; re-minting it from the (still
// server-side, still encrypted-at-rest) refresh token is cheap.
let driveAccessTokenCache = null; // { token, expiresAt } | null

async function getDriveAccessToken() {
  const now = Date.now();
  if (driveAccessTokenCache && driveAccessTokenCache.expiresAt && driveAccessTokenCache.expiresAt - now > 60000) {
    return driveAccessTokenCache.token;
  }
  const data = await apiRequest("/drive/access-token");
  driveAccessTokenCache = { token: data.accessToken, expiresAt: data.expiresAt || now + 55 * 60 * 1000 };
  return driveAccessTokenCache.token;
}

async function loadDriveConnectionStatus() {
  return apiRequest("/drive/backup-status");
}

// Opens the real Google OAuth consent screen in a popup and waits for the
// connection to actually land in the backend (polling GET /backup-status)
// rather than trying to postMessage with the callback page — see that
// route's own comment in clairmd-backend for why. Bails out if the doctor
// closes the popup before finishing, or after 2 minutes either way.
async function startDriveConnection() {
  const data = await apiRequest("/drive/oauth/start");
  const popup = window.open(data.authUrl, "clairmd-drive-oauth", "width=520,height=680");
  if (!popup) {
    throw new Error("Popup blocked — allow popups for this site, then try again.");
  }
  const deadline = Date.now() + 120000;
  while (Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 2000));
    const status = await loadDriveConnectionStatus().catch(() => null);
    if (status?.connected) {
      if (!popup.closed) popup.close();
      return status;
    }
    if (popup.closed) {
      throw new Error("Google Drive connection window was closed before finishing.");
    }
  }
  if (!popup.closed) popup.close();
  throw new Error("Timed out waiting for the Google Drive connection to complete.");
}

function getCachedDriveFileId(recordId) {
  return typeof localStorage !== "undefined" ? localStorage.getItem(`clair_drive_file_${recordId}`) : null;
}
function setCachedDriveFileId(recordId, fileId) {
  if (typeof localStorage !== "undefined") localStorage.setItem(`clair_drive_file_${recordId}`, fileId);
}

// Uploads (first save) or updates (every save after) this record's
// encrypted blob as a file in the doctor's own Drive, inside the
// dedicated app folder the OAuth callback already created server-side.
// The multipart body's metadata part carries only a non-descriptive
// filename — the content part is the SAME opaque base64 ciphertext string
// already sent to /api/record-content, so Drive never sees anything this
// backend doesn't already treat as opaque either.
async function uploadEncryptedBlobToDrive(recordId, encryptedBlob) {
  const [accessToken, status] = await Promise.all([getDriveAccessToken(), loadDriveConnectionStatus()]);
  const existingFileId = getCachedDriveFileId(recordId);

  const metadata = { name: `clairmd-record-${recordId}.enc` };
  // parents is only valid on CREATE — Drive v3 rejects it on an update
  // body (moving a file needs addParents/removeParents query params
  // instead), so this is only ever set for a brand-new file.
  if (!existingFileId && status.appFolderId) metadata.parents = [status.appFolderId];

  const boundary = "clairmd-boundary";
  const body =
    `--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify(metadata)}\r\n` +
    `--${boundary}\r\nContent-Type: text/plain\r\n\r\n${encryptedBlob}\r\n--${boundary}--`;

  const url = existingFileId ? `${DRIVE_UPLOAD_URL}/${existingFileId}?uploadType=multipart` : `${DRIVE_UPLOAD_URL}?uploadType=multipart`;
  const res = await fetch(url, {
    method: existingFileId ? "PATCH" : "POST",
    headers: { Authorization: `Bearer ${accessToken}`, "Content-Type": `multipart/related; boundary=${boundary}` },
    body,
  });
  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`Google Drive upload failed (${res.status}): ${text.slice(0, 200)}`);
  }
  const data = await res.json();
  setCachedDriveFileId(recordId, data.id);
  return data.id;
}

// Resolves which real Drive file backs a record. Prefers this browser's
// own cache (set the moment it uploaded); falls back to the backend's
// pointer row, which uploadEncryptedBlobToDrive/syncNoteToBackend keep in
// sync via PATCH /api/records/:id — needed for e.g. a fresh browser
// profile that never did the upload itself.
async function resolveDriveFileId(recordId) {
  const cached = getCachedDriveFileId(recordId);
  if (cached) return cached;
  const data = await apiRequest(`/records/${recordId}`);
  if (!data.record.drive_file_id || data.record.drive_file_id.startsWith("clair-prototype-")) {
    throw new Error("This record hasn't been uploaded to Google Drive yet.");
  }
  setCachedDriveFileId(recordId, data.record.drive_file_id);
  return data.record.drive_file_id;
}

async function downloadEncryptedBlobFromDrive(recordId) {
  const [accessToken, fileId] = await Promise.all([getDriveAccessToken(), resolveDriveFileId(recordId)]);
  const res = await fetch(`${DRIVE_FILES_URL}/${fileId}?alt=media`, { headers: { Authorization: `Bearer ${accessToken}` } });
  if (!res.ok) throw new Error(`Google Drive download failed (${res.status}).`);
  return res.text();
}

async function recordDriveBackupEvent(status, extra = {}) {
  return apiRequest("/drive/backup-events", { method: "POST", body: { status, ...extra } });
}

// --- Hospital Razorpay payment method — real Checkout.js integration ----
// Loads Razorpay's real checkout script on demand (not bundled — most
// accounts using this app are never hospitals hitting ICU/Ward overage).
let razorpayScriptPromise = null;
function loadRazorpayCheckoutScript() {
  if (typeof window === "undefined") return Promise.reject(new Error("Not in a browser context."));
  if (window.Razorpay) return Promise.resolve();
  if (razorpayScriptPromise) return razorpayScriptPromise;
  razorpayScriptPromise = new Promise((resolve, reject) => {
    const script = document.createElement("script");
    script.src = "https://checkout.razorpay.com/v1/checkout.js";
    script.onload = () => resolve();
    script.onerror = () => { razorpayScriptPromise = null; reject(new Error("Couldn't load Razorpay's checkout script — check your connection.")); };
    document.body.appendChild(script);
  });
  return razorpayScriptPromise;
}

async function loadHospitalPaymentMethodStatus() {
  const data = await apiRequest("/hospital-billing/payment-method/status");
  return data.hasPaymentMethod;
}
async function loadHospitalOverageStatus() {
  return apiRequest("/hospital-billing/overage-status");
}

// The full "add a payment method" flow: create a real order
// (POST /hospital-billing/setup-order), open Razorpay's real Checkout
// widget with recurring/tokenization requested, then hand the completed
// checkout's reference to the backend for independent signature
// verification — this never trusts the client-side success callback
// alone (see routes/hospitalBilling.js's /setup-order/verify, which
// re-derives the signature itself). Resolves once the backend has
// actually saved a verified payment method, not just once Razorpay's
// popup reports success.
async function addHospitalPaymentMethod(hospitalEmail, hospitalDisplayName) {
  await loadRazorpayCheckoutScript();
  const { order, razorpayKeyId } = await apiRequest("/hospital-billing/setup-order", { method: "POST" });

  const checkoutResult = await new Promise((resolve, reject) => {
    const rzp = new window.Razorpay({
      key: razorpayKeyId,
      amount: order.amount,
      currency: order.currency,
      order_id: order.id,
      name: "ClairMD Clinic",
      description: "Link a payment method for hospital overage billing",
      recurring: 1, // ask Razorpay to tokenize this method for future unattended charges
      prefill: { email: hospitalEmail, name: hospitalDisplayName },
      handler: (response) => resolve(response),
      modal: { ondismiss: () => reject(new Error("Payment window closed before completing.")) },
    });
    rzp.on("payment.failed", (response) => reject(new Error(response.error?.description || "Payment failed.")));
    rzp.open();
  });

  return apiRequest("/hospital-billing/setup-order/verify", {
    method: "POST",
    body: {
      razorpayOrderId: checkoutResult.razorpay_order_id,
      razorpayPaymentId: checkoutResult.razorpay_payment_id,
      razorpaySignature: checkoutResult.razorpay_signature,
    },
  });
}

// --- Hospital affiliations — doctor-initiated request + hospital
// approve/decline (clairmd-backend's routes/hospitalAffiliations.js). The
// hospital's own direct-add flow already existed backend-side but was
// never wired to any frontend UI at all — not even a read-only "your
// affiliated doctors" list — so this covers both sides. -------------------
async function requestHospitalAffiliation(hospitalAccountId) {
  const data = await apiRequest("/hospital-affiliations/requests", { method: "POST", body: { hospitalAccountId } });
  return data.request;
}
async function loadMyAffiliationRequests() {
  const data = await apiRequest("/hospital-affiliations/requests/mine");
  return data.requests;
}
async function loadMyHospitalAffiliations() {
  const data = await apiRequest("/hospital-affiliations/mine");
  return data.affiliations;
}
async function loadPendingAffiliationRequestsForHospital() {
  const data = await apiRequest("/hospital-affiliations/requests/pending");
  return data.requests;
}
async function approveAffiliationRequestOnBackend(id) {
  const data = await apiRequest(`/hospital-affiliations/requests/${id}/approve`, { method: "POST" });
  return data.affiliation;
}
async function declineAffiliationRequestOnBackend(id) {
  await apiRequest(`/hospital-affiliations/requests/${id}/decline`, { method: "POST" });
}
async function loadHospitalAffiliatedDoctors() {
  const data = await apiRequest("/hospital-affiliations");
  return data.affiliations;
}

// Full round trip: create the pointer, encrypt the note, PUT it to the
// backend's opaque-blob store, then GET + decrypt it straight back to
// confirm the backend genuinely stored what was sent. Then, if this
// doctor has Google Drive connected, does the SAME thing again against
// Drive itself — upload the ciphertext, download it straight back,
// decrypt, and compare — since Drive (not this backend) is the intended
// primary durable copy (see patient_record_content's design comment in
// clairmd-backend's schema.sql). The Drive half is best-effort: a
// failure there (not connected, popup never finished, token expired)
// never throws — the already-verified backend sync stands on its own —
// it's surfaced in the returned object instead, so a caller CAN show it
// without being forced to handle it as an error.
async function syncNoteToBackend(noteType, noteText) {
  const recordId = await ensureBackendRecord(noteType);
  const encryptedBlob = await encryptRecordText(recordId, noteText);
  await apiRequest(`/record-content/${recordId}`, { method: "PUT", body: { encryptedBlob } });

  const fetched = await apiRequest(`/record-content/${recordId}`);
  const roundTripText = await decryptRecordText(recordId, fetched.content.encrypted_blob);
  if (roundTripText !== noteText) {
    throw new Error("Backend round-trip verification failed — decrypted content didn't match what was sent.");
  }

  let driveSynced = false;
  let driveError = null;
  try {
    const status = await loadDriveConnectionStatus();
    if (status.connected) {
      await uploadEncryptedBlobToDrive(recordId, encryptedBlob);
      const driveBlob = await downloadEncryptedBlobFromDrive(recordId);
      const driveRoundTrip = await decryptRecordText(recordId, driveBlob);
      if (driveRoundTrip !== noteText) {
        throw new Error("Drive round-trip verification failed — decrypted content didn't match what was sent.");
      }
      await apiRequest(`/records/${recordId}`, { method: "PATCH", body: { driveFileId: getCachedDriveFileId(recordId) } });
      await recordDriveBackupEvent("success", { fileSizeBytes: encryptedBlob.length });
      driveSynced = true;
    }
  } catch (err) {
    driveError = err.message;
    recordDriveBackupEvent("failed", { errorMessage: err.message.slice(0, 500) }).catch(() => {});
  }

  return { recordId, driveSynced, driveError };
}

// Several actions (lab orders, referrals, care-team instructions) need
// *some* patient_record_index row to hang off, but unlike an OPD/ICU-Ward
// save there's no natural "save" moment that creates one — e.g. a test
// can be ordered before any note for this encounter has been saved at
// all. Rather than mint a new backend record per action (noisy, and
// wrong: multiple actions for one patient in one session should share a
// record), this lazily creates ONE record per patient the first time any
// of them needs one, then reuses it for all of them — cached in
// localStorage the same way per-record encryption keys already are.
async function getOrCreatePatientRecordId(patientId) {
  const storageKey = `clair_lab_record_${patientId}`;
  const existing = localStorage.getItem(storageKey);
  if (existing) return existing;
  const recordId = await ensureBackendRecord("opd");
  localStorage.setItem(storageKey, recordId);
  return recordId;
}

// Lab order metadata (which test, which category, is it done) is sent as
// plaintext, unlike the note content above — see clairmd-backend's
// schema.sql comment on lab_orders for why: a lab order only does its job
// if a party without chart access can read what's actually being ordered.
async function syncLabOrderToBackend(patientId, category, testName) {
  const patientRecordId = await getOrCreatePatientRecordId(patientId);
  const data = await apiRequest("/lab-orders", { method: "POST", body: { patientRecordId, category, testName } });
  return { orderId: data.order.id };
}

// --- Bed availability (hospital account only) --------------------------
async function syncBedStatusToBackend(totalBeds, availableBeds) {
  const data = await apiRequest("/bed-availability", { method: "PUT", body: { totalBeds, availableBeds } });
  return data.bedStatus;
}
async function loadBedStatusFromBackend() {
  const data = await apiRequest("/bed-availability");
  return data.bedStatus;
}

// --- Inventory (hospital account only) ----------------------------------
// The frontend's INVENTORY_CATEGORIES are Title Case ("Medication", "PPE");
// the backend's enum is lowercase — converted at this boundary only, so
// neither side has to know about the other's casing convention. A plain
// capitalize-first-letter doesn't round-trip "ppe" -> "PPE" correctly,
// hence the explicit map rather than a generic transform.
const INVENTORY_CATEGORY_DISPLAY = { medication: "Medication", consumable: "Consumable", equipment: "Equipment", ppe: "PPE", other: "Other" };

async function loadInventoryFromBackend() {
  const data = await apiRequest("/inventory");
  return data.items.map((i) => ({
    backendId: i.id, name: i.name, category: INVENTORY_CATEGORY_DISPLAY[i.category] || i.category,
    quantity: i.quantity, unit: i.unit, reorderAt: i.reorder_at, expiryDate: i.expiry_date || "", supplier: i.supplier || "",
  }));
}
async function createInventoryItemOnBackend(item) {
  const data = await apiRequest("/inventory", {
    method: "POST",
    body: { name: item.name, category: item.category.toLowerCase(), quantity: item.quantity, unit: item.unit, reorderAt: item.reorderAt, expiryDate: item.expiryDate || undefined, supplier: item.supplier || undefined },
  });
  return data.item.id;
}
async function adjustInventoryItemOnBackend(backendId, delta) {
  await apiRequest(`/inventory/${backendId}/adjust`, { method: "POST", body: { delta } });
}
async function deleteInventoryItemOnBackend(backendId) {
  await apiRequest(`/inventory/${backendId}`, { method: "DELETE" });
}

// --- Patient follow-ups --------------------------------------------------
// Follow-up plans in this prototype are pre-seeded, not created through
// any UI — so, same lazy-create-on-first-real-action shape as lab orders'
// getOrCreateLabRecordId, the backend row is created the first time a
// message is actually sent for a given local plan, then cached and reused
// for every later message on that same plan.
async function getOrCreateFollowupRecordId(localFollowup) {
  const storageKey = `clair_followup_record_${localFollowup.id}`;
  const existing = localStorage.getItem(storageKey);
  if (existing) return existing;
  const data = await apiRequest("/follow-ups", {
    method: "POST",
    body: {
      patientDisplayName: localFollowup.patient || "Unknown patient",
      patientPhone: localFollowup.phone || undefined,
      interval: localFollowup.interval,
      takeaways: localFollowup.takeaways,
      complications: localFollowup.complications || undefined,
      dietPhysio: localFollowup.dietPhysio || undefined,
      precautions: localFollowup.precautions || undefined,
      nextVisit: localFollowup.nextVisit || undefined,
    },
  });
  localStorage.setItem(storageKey, data.followup.id);
  return data.followup.id;
}
async function syncFollowupMessageToBackend(localFollowup, text, isAdviceLink, linkExpiresAtMs) {
  const followupId = await getOrCreateFollowupRecordId(localFollowup);
  await apiRequest(`/follow-ups/${followupId}/messages`, {
    method: "POST",
    body: { text, isAdviceLink: !!isAdviceLink, linkExpiresAt: linkExpiresAtMs ? new Date(linkExpiresAtMs).toISOString() : undefined },
  });
}

