// Compact, reusable connect/status widget — email+password only (matches
// the real backend's actual signup/login fields; the license-number field
// only appears for doctor account types, since /api/auth/signup requires
// it for those). Deliberately separate from the flashy multi-step signup
// wizard elsewhere in this file (that one simulates the full product UX;
// this one just needs to get a real token from the real backend).
function BackendSyncPanel({ accountType = "individual_doctor", notConnectedLabel = "Backend: not connected — notes save locally only", onConnected }) {
  const isDoctorType = accountType === "individual_doctor" || accountType === "hospital_doctor";
  const [open, setOpen] = useState(false);
  const [mode, setMode] = useState("login"); // login | signup
  const [email, setEmail] = useState("");
  const [password, setPassword] = useState("");
  const [displayName, setDisplayName] = useState("");
  const [licenseNumber, setLicenseNumber] = useState("");
  const [connectedEmail, setConnectedEmail] = useState(null);
  const [status, setStatus] = useState(null); // { type: "error"|"success", text }
  const [busy, setBusy] = useState(false);

  // A token from an earlier BackendSyncPanel instance (a different
  // surface, or an earlier page load) already lives in localStorage — the
  // fresh local `connectedEmail` state above starts null regardless, so
  // without this every new instance would show "not connected" even
  // though the whole point of storing the token in localStorage is that
  // it's already good to go. An invalid/expired token is cleared rather
  // than left around to keep silently failing every request that uses it.
  useEffect(() => {
    if (!getAuthToken()) return;
    apiRequest("/auth/me").then((data) => { setConnectedEmail(data.account.email); onConnected?.(data.account); }).catch(() => setAuthToken(null));
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const submit = async (e) => {
    e.preventDefault();
    setBusy(true);
    setStatus(null);
    try {
      const account = mode === "signup"
        ? await backendSignup({ accountType, email, password, displayName, licenseNumber })
        : await backendLogin({ email, password });
      setConnectedEmail(account.email);
      setStatus({ type: "success", text: `Connected to backend as ${account.email}.` });
      // Lets a parent panel react to a FRESH connection (e.g. re-fetch its
      // own data, or — CoAdminPanel — publish this account's public key)
      // rather than relying on an incidental re-render to notice the new
      // token, which isn't guaranteed to happen right after signup/login.
      onConnected?.(account);
    } catch (err) {
      setStatus({ type: "error", text: err.message });
    } finally {
      setBusy(false);
    }
  };

  if (connectedEmail) {
    return (
      <div className="flex items-center gap-2 text-[11px] text-[#5B6B63]" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>
        <span className="w-1.5 h-1.5 rounded-full bg-[#0F5C56]" />
        Backend: connected as {connectedEmail}
        <button type="button" onClick={() => { backendLogout(); setConnectedEmail(null); }} className="underline text-[#8A958E] hover:text-[#B34A3C]">
          Disconnect
        </button>
      </div>
    );
  }

  return (
    <div className="border border-[#D8DED9] rounded-sm bg-[#F7F9F7] p-2.5">
      <button type="button" onClick={() => setOpen((v) => !v)} className="flex items-center gap-1.5 text-[11px] text-[#5B6B63]" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>
        {open ? <ChevronDown size={12} /> : <ChevronRight size={12} />}
        {notConnectedLabel}
      </button>
      {open && (
        <form onSubmit={submit} className="mt-2 space-y-1.5">
          <div className="flex gap-1.5 mb-1">
            {["login", "signup"].map((m) => (
              <button
                key={m}
                type="button"
                onClick={() => setMode(m)}
                className={`text-[10px] px-2 py-0.5 rounded-full border font-medium ${mode === m ? "text-white border-[#0F5C56]" : "border-[#D8DED9] text-[#5B6B63]"}`}
                style={mode === m ? { backgroundColor: "#0F5C56" } : {}}
              >
                {m === "login" ? "Log in" : "Sign up"}
              </button>
            ))}
          </div>
          <input type="email" required value={email} onChange={(e) => setEmail(e.target.value)} placeholder="Email" className="w-full px-2 py-1 border border-[#D8DED9] rounded-sm text-xs" />
          <input type="password" required value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Password" className="w-full px-2 py-1 border border-[#D8DED9] rounded-sm text-xs" />
          {mode === "signup" && (
            <>
              <input required value={displayName} onChange={(e) => setDisplayName(e.target.value)} placeholder="Display name" className="w-full px-2 py-1 border border-[#D8DED9] rounded-sm text-xs" />
              {isDoctorType && (
                <input required value={licenseNumber} onChange={(e) => setLicenseNumber(e.target.value)} placeholder="Medical license number" className="w-full px-2 py-1 border border-[#D8DED9] rounded-sm text-xs" />
              )}
            </>
          )}
          <button type="submit" disabled={busy} className="text-[11px] px-2.5 py-1 rounded-sm text-white font-medium" style={{ backgroundColor: "#0F5C56" }}>
            {busy ? "Connecting…" : mode === "login" ? "Log in" : "Create account"}
          </button>
          {status && (
            <p className={`text-[10px] ${status.type === "error" ? "text-[#B34A3C]" : "text-[#0F5C56]"}`}>{status.text}</p>
          )}
        </form>
      )}
    </div>
  );
}

// Human-readable label per notification_type — the raw payload only ever
// carries ids (referralId, fromDoctorId, ...), never a display name, so
// this stays a generic label rather than trying to resolve those ids into
// names (that would mean extra lookups the notifications endpoint itself
// doesn't provide).
const NOTIFICATION_TYPE_LABELS = {
  referral_created: "New referral received",
  referral_responded: "Your referral was responded to",
  care_team_instruction_created: "New care-team instruction",
  care_team_instruction_acknowledged: "Instruction acknowledged",
};
function describeNotification(n) {
  if (n.notification_type === "referral_responded" && n.payload?.status) {
    return `Your referral was ${n.payload.status}`;
  }
  return NOTIFICATION_TYPE_LABELS[n.notification_type] || n.notification_type;
}

// Poll-based, matching clairmd-backend's own design (its README is
// explicit that no real push/email delivery is wired server-side either)
// — this polls GET /api/notifications on an interval rather than
// expecting a live push, since there genuinely isn't one to expect yet.
function NotificationsBell() {
  const [open, setOpen] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [connectedEmail, setConnectedEmail] = useState(null);
  const menuRef = useRef(null);

  useEffect(() => {
    if (!getAuthToken()) return;
    apiRequest("/auth/me").then((data) => setConnectedEmail(data.account.email)).catch(() => {});
  }, []);

  const refresh = () => {
    if (!getAuthToken()) return;
    loadNotifications().then(setNotifications).catch(() => {});
  };
  useEffect(() => {
    refresh();
    const interval = setInterval(refresh, 30000);
    return () => clearInterval(interval);
  }, []);

  useEffect(() => {
    if (!open) return;
    const handlePointerDown = (e) => { if (menuRef.current && !menuRef.current.contains(e.target)) setOpen(false); };
    document.addEventListener("mousedown", handlePointerDown);
    return () => document.removeEventListener("mousedown", handlePointerDown);
  }, [open]);

  const markRead = (id) => {
    markNotificationReadOnBackend(id)
      .then(() => setNotifications((prev) => prev.map((n) => (n.id === id ? { ...n, read_at: new Date().toISOString() } : n))))
      .catch(() => {});
  };

  const unreadCount = notifications.filter((n) => !n.read_at).length;

  return (
    <div className="relative" ref={menuRef}>
      <button
        type="button"
        onClick={() => setOpen((v) => !v)}
        title="Notifications"
        className="relative w-8 h-8 flex items-center justify-center rounded-sm text-[#5B6B63] hover:bg-[#F7F9F7] hover:text-[#16241F]"
      >
        <Bell size={16} />
        {unreadCount > 0 && (
          <span className="absolute top-0.5 right-0.5 min-w-[14px] h-[14px] px-0.5 flex items-center justify-center text-[9px] font-medium text-white bg-[#B34A3C] rounded-full">
            {unreadCount > 9 ? "9+" : unreadCount}
          </span>
        )}
      </button>
      {open && (
        <div className="absolute right-0 mt-1 w-72 bg-white border border-[#D8DED9] rounded-sm shadow-xl z-50">
          <div className="px-3 py-2 border-b border-[#D8DED9] flex items-center justify-between">
            <span className="text-[11px] uppercase tracking-wide text-[#8A958E]" style={{ fontFamily: "'IBM Plex Mono', monospace" }}>Notifications</span>
            {getAuthToken() && <button onClick={refresh} className="text-[10px] text-[#0F5C56] underline decoration-dotted">Refresh</button>}
          </div>
          {!connectedEmail ? (
            <div className="p-3">
              <p className="text-xs text-[#8A958E] mb-2" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>Connect to the backend to see real notifications — referrals and care-team instructions enqueue these for real once you are.</p>
              <BackendSyncPanel accountType="individual_doctor" notConnectedLabel="Backend: not connected" />
            </div>
          ) : notifications.length === 0 ? (
            <p className="text-xs text-[#8A958E] p-3" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>No notifications yet.</p>
          ) : (
            <div className="max-h-72 overflow-y-auto">
              {notifications.map((n) => (
                <div key={n.id} className={`px-3 py-2 border-b border-[#EEF1EE] flex items-start justify-between gap-2 ${n.read_at ? "" : "bg-[#F2F7F5]"}`}>
                  <div>
                    <div className="text-xs" style={{ fontFamily: "'IBM Plex Sans', sans-serif", color: "#16241F" }}>{describeNotification(n)}</div>
                    <div className="text-[10px] text-[#8A958E] mt-0.5">{new Date(n.created_at).toLocaleString()}</div>
                  </div>
                  {!n.read_at && (
                    <button onClick={() => markRead(n.id)} className="text-[10px] text-[#0F5C56] underline decoration-dotted shrink-0">Mark read</button>
                  )}
                </div>
              ))}
            </div>
          )}
        </div>
      )}
    </div>
  );
}

