function matchNgos(patient) {
  const isCancerOrComplex = patient.encounters.some((e) => e.isComplex || e.diagnosisKey === "myeloma");
  return NGO_DIRECTORY.filter((n) => {
    if (n.scope === "palliative" && !isCancerOrComplex) return false;
    return n.eligibility.includes(patient.category);
  });
}

