function SSField({ field, value, onChange }) {
  const { handleContextMenu, portal } = useDiagnosticLookup();
  if (field.type === "checklist") {
    const current = value || [];
    const toggle = (opt) => onChange(current.includes(opt) ? current.filter((o) => o !== opt) : [...current, opt]);
    return (
      <div className="mb-2.5">
        <label className="block text-[10px] font-medium text-[#5B6B63] mb-1.5" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>{field.label}</label>
        <div className="flex flex-wrap gap-1.5">
          {field.options.map((opt) => (
            <label
              key={opt}
              className="flex items-center gap-1 text-[10px] px-2 py-1 rounded-sm border cursor-pointer"
              style={{ fontFamily: "'IBM Plex Sans', sans-serif", borderColor: current.includes(opt) ? "#B34A3C" : "#D8DED9", backgroundColor: current.includes(opt) ? "#FBEFEC" : "#FFFFFF", color: current.includes(opt) ? "#B34A3C" : "#3C4A42" }}
            >
              <input type="checkbox" checked={current.includes(opt)} onChange={() => toggle(opt)} className="accent-[#B34A3C]" />
              {opt}
            </label>
          ))}
        </div>
      </div>
    );
  }
  const commonProps = {
    value: value || "",
    onChange: (e) => onChange(e.target.value),
    className: "w-full px-2.5 py-1.5 border border-[#D8DED9] rounded-sm text-xs bg-white",
    style: { fontFamily: "'IBM Plex Mono', monospace" },
    placeholder: field.placeholder || "—",
  };
  return (
    <div className="mb-2.5">
      <label className="block text-[10px] font-medium text-[#5B6B63] mb-1" style={{ fontFamily: "'IBM Plex Sans', sans-serif" }}>{field.label}</label>
      {field.type === "select" ? (
        <select {...commonProps}>
          <option value="">— select —</option>
          {field.options.map((opt) => <option key={opt} value={opt}>{opt}</option>)}
        </select>
      ) : field.type === "textarea" ? (
        <textarea {...commonProps} onContextMenu={handleContextMenu} className={commonProps.className + " min-h-[52px]"} />
      ) : (
        <input type="text" {...commonProps} onContextMenu={handleContextMenu} />
      )}
      {portal}
    </div>
  );
}

